-- Импорт перечня изданий КОКСНВО МНВО РК из «Журналы_со_ссылками.xlsx»
-- (Списки 1, 2, 3 и список журналов ВСУЗов) со ссылками на сайты журналов.
--
-- Для каждой ссылки OAI-PMH endpoint искался автоматически и проверялся вживую
-- (verb=Identify + verb=ListRecords&metadataPrefix=oai_dc) 2026-10-09. Журналы без
-- найденного OAI-PMH добавлены в реестр с crawler_type='manual' и oai_endpoint=null —
-- харвестер их пропускает, но они видны в каталоге и в фильтре КОКСНВО.
-- Дубли (один журнал в двух списках / под старым названием) схлопнуты по OAI endpoint.

-- 4 = список журналов ВСУЗов (военных и специальных учебных заведений)
alter table journals drop constraint if exists journals_koksnvo_list_check;
alter table journals add constraint journals_koksnvo_list_check check (koksnvo_list in (1, 2, 3, 4));

alter table journals add column if not exists koksnvo_included_from text;
-- Часть сайтов (Elpub/NEICON и др.) обрывает соединение для нестандартного User-Agent.
alter table journals add column if not exists oai_browser_user_agent boolean not null default false;
-- Состояние харвеста: позиция для продолжения и последняя ошибка.
alter table journals add column if not exists harvest_resumption_token text;
alter table journals add column if not exists harvest_error text;
alter table journals add column if not exists harvest_error_at timestamptz;

update journals set koksnvo_included_from = 'ақпан 2021 жыл'
where name like 'Bulletin of L.N. Gumilyov%' or name like 'Herald of Journalism%'
   or name like 'Bulletin of the Karaganda%';

insert into journals (
  name, publisher, base_url, platform, oai_endpoint, crawler_type, discipline,
  koksnvo_list, koksnvo_order, koksnvo_included_from, oai_browser_user_agent, notes
)
