-- Профиль журнала: + ошибка харвеста и дата включения в перечень.
drop function if exists journal_profiles();

create function journal_profiles()
returns table (
  id uuid,
  name text,
  publisher text,
  base_url text,
  platform text,
  oai_endpoint text,
  issn_print text,
  issn_online text,
  language text,
  open_access boolean,
  discipline text,
  source_type text,
  koksnvo_list smallint,
  koksnvo_order text,
  koksnvo_included_from text,
  last_crawled_at timestamptz,
  harvest_error text,
  article_count bigint
)
language sql stable
as $$
  select
    j.id, j.name, j.publisher, j.base_url, j.platform, j.oai_endpoint,
    j.issn_print, j.issn_online, j.language, j.open_access, j.discipline,
    j.source_type, j.koksnvo_list, j.koksnvo_order, j.koksnvo_included_from,
    j.last_crawled_at, j.harvest_error,
    count(a.id) as article_count
  from journals j
  left join articles a on a.journal_id = j.id
  group by j.id
  order by count(a.id) desc, j.name;
$$;

-- Поиск: фильтры по журналу и списку КОКСНВО теперь на сервере. Раньше фронтенд
-- фильтровал топ-40 на клиенте — при ~200 журналах это почти всегда давало пустую выдачу.
drop function if exists search_articles(text, int);

create function search_articles(
  query text,
  limit_count int default 20,
  journal_filter uuid default null,
  koksnvo_filter smallint default null
)
returns table (
  id uuid,
  journal_id uuid,
  journal_name text,
  title text,
  authors text,
  abstract text,
  doi text,
  publication_date date,
  volume text,
  issue text,
  pages text,
  language text,
  article_url text,
  pdf_url text,
  metadata_quality text,
  cited_by_count int,
  cited_by_scopus_count int,
  citing_works jsonb,
  rank real
)
language sql stable
as $$
  select
    a.id,
    a.journal_id,
    j.name as journal_name,
    a.title,
    a.authors,
    a.abstract,
    a.doi,
    a.publication_date,
    a.volume,
    a.issue,
    a.pages,
    a.language,
    a.article_url,
    a.pdf_url,
    a.metadata_quality,
    a.cited_by_count,
    a.cited_by_scopus_count,
    a.citing_works,
    ts_rank(a.search_vector, websearch_to_tsquery('russian', query)) as rank
  from articles a
  join journals j on j.id = a.journal_id
  where a.search_vector @@ websearch_to_tsquery('russian', query)
    and (journal_filter is null or a.journal_id = journal_filter)
    and (koksnvo_filter is null or j.koksnvo_list = koksnvo_filter)
  order by rank desc
  limit limit_count;
$$;
